UPDATE ifj_app_run
SET status = 'CRASHED', stopped_at = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE run_id IN (
    SELECT run_id FROM (
        SELECT run_id FROM ifj_app_run
        WHERE status IN ('STARTING', 'RUNNING', 'DRAINING')
          AND run_id <> #{excludeRunId}
          AND heartbeat_at <= CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) - NUMTODSINTERVAL(#{staleMicros} / 1000000, 'SECOND')
        ORDER BY heartbeat_at, run_id
    ) WHERE ROWNUM <= #{limit}
)
